def check_exception_instantiable(self, typ: ProperType, context: Context) -> None:
    """Check that an exception class used in a raise statement can be instantiated.

    Python implicitly instantiates exception classes in e.g. `raise SomeError`,
    so the class must be callable with no arguments.
    """
    if isinstance(typ, TypeType):
        item = get_proper_type(typ.item)
        if isinstance(item, Instance):
            callee = type_object_type(item.type, self.named_type)
        else:
            return
    elif isinstance(typ, FunctionLike) and typ.is_type_obj():
        callee = typ
    else:
        return
    exc_type = self.named_type('builtins.BaseException')
    if isinstance(callee, CallableType):
        if not is_subtype(callee.ret_type, exc_type):
            return
    elif isinstance(callee, Overloaded):
        if not all(is_subtype(item.ret_type, exc_type) for item in callee.items):
            return
    else:
        return
    self.expr_checker.check_call(callee, [], [], context)
